import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

export default defineConfig({
  plugins: [react(), tailwindcss()],
});

{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2023"],
    "module": "ESNext",
    "skipLibCheck": true,
    "moduleResolution": "bundler"
  },
  "include": ["vite.config.ts"]
}

@import "tailwindcss";

@theme {
  --font-sans: "DM Sans", system-ui, sans-serif;
  --font-display: "Instrument Serif", Georgia, serif;

  --color-brand-50: #f4f7f4;
  --color-brand-100: #e3ebe3;
  --color-brand-200: #c5d6c6;
  --color-brand-300: #9bb89d;
  --color-brand-400: #6d9470;
  --color-brand-500: #4a7350;
  --color-brand-600: #385c3d;
  --color-brand-700: #2e4a32;
  --color-brand-800: #273d2a;
  --color-brand-900: #213325;

  --color-accent-500: #c17f3a;
  --color-accent-600: #a66a2f;

  --color-surface: #faf9f7;
  --color-panel: #ffffff;
  --color-ink: #1a1f1c;
  --color-muted: #5c6760;
  --color-line: #e8e6e1;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  background: var(--color-surface);
  color: var(--color-ink);
  -webkit-font-smoothing: antialiased;
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-thumb {
  background: var(--color-brand-300);
  border-radius: 3px;
}

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./index.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import {
  BarChart3,
  Building2,
  LayoutDashboard,
  Package,
  Settings,
  ShoppingCart,
  Users,
  type LucideIcon,
} from "lucide-react";
import { navItems } from "../data/mockData";

const iconMap: Record<string, LucideIcon> = {
  LayoutDashboard,
  Package,
  Building2,
  ShoppingCart,
  Users,
  BarChart3,
  Settings,
};

type SidebarProps = {
  active: string;
  onNavigate: (id: string) => void;
};

export function Sidebar({ active, onNavigate }: SidebarProps) {
  return (
    <aside className="flex h-full w-64 shrink-0 flex-col border-r border-line bg-panel">
      <motion.div className="border-b border-line px-6 py-5">
        <motion.div className="flex items-center gap-3">
          <motion.div className="flex h-10 w-10 items-center justify-center rounded-lg bg-brand-600 text-sm font-bold text-white">
            BM
          </motion.div>
          <motion.div>
            <p className="font-display text-xl leading-tight text-ink">BuildMart</p>
            <p className="text-xs text-muted">Admin Panel</p>
          </motion.div>
        </motion.div>
      </motion.div>

      <nav className="flex-1 space-y-1 overflow-y-auto px-3 py-4">
        {navItems.map((item) => {
          const Icon = iconMap[item.icon];
          const isActive = active === item.id;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => onNavigate(item.id)}
              className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors ${
                isActive
                  ? "bg-brand-600 text-white"
                  : "text-muted hover:bg-brand-50 hover:text-ink"
              }`}
            >
              <Icon size={18} strokeWidth={isActive ? 2.25 : 2} />
              {item.label}
            </button>
          );
        })}
      </nav>

      <motion.div className="border-t border-line p-4">
        <motion.div className="rounded-lg bg-brand-50 p-3">
          <p className="text-xs font-semibold text-brand-700">Paket Bisnis</p>
          <p className="mt-1 text-xs text-muted">Kelola hingga 5 cabang toko</p>
          <button
            type="button"
            className="mt-2 w-full rounded-md bg-brand-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-700"
          >
            Upgrade
          </button>
        </motion.div>
      </motion.div>
    </aside>
  );
}

