import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import type { ReactNode } from "react";

type StatCardProps = {
  label: string;
  value: string;
  change: string;
  up?: boolean;
  icon: ReactNode;
  accent?: "brand" | "accent" | "neutral";
};

export function StatCard({ label, value, change, up = true, icon, accent = "brand" }: StatCardProps) {
  const accentBg =
    accent === "accent"
      ? "bg-accent-500/10 text-accent-600"
      : accent === "neutral"
        ? "bg-brand-100 text-brand-700"
        : "bg-brand-100 text-brand-600";

  return (
    <article className="rounded-xl border border-line bg-panel p-5">
      <section className="flex items-start justify-between">
        <span className={`flex h-10 w-10 items-center justify-center rounded-lg ${accentBg}`}>
          {icon}
        </span>
        <span
          className={`flex items-center gap-0.5 text-xs font-semibold ${
            up ? "text-brand-600" : "text-accent-600"
          }`}
        >
          {up ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />}
          {change}
        </span>
      </section>
      <p className="mt-4 text-2xl font-semibold tracking-tight text-ink">{value}</p>
      <p className="mt-1 text-sm text-muted">{label}</p>
    </article>
  );
}

import { Cell, Pie, PieChart, ResponsiveContainer, Tooltip } from "recharts";
import { categoryBreakdown } from "../data/mockData";

export function CategoryChart() {
  return (
    <article className="rounded-xl border border-line bg-panel p-6">
      <header className="mb-4">
        <h2 className="text-base font-semibold text-ink">Kategori Material</h2>
        <p className="text-sm text-muted">Distribusi penjualan per kategori (%)</p>
      </header>

      <ResponsiveContainer width="100%" height={220}>
        <PieChart>
          <Pie
            data={categoryBreakdown}
            cx="50%"
            cy="50%"
            innerRadius={55}
            outerRadius={85}
            paddingAngle={3}
            dataKey="value"
          >
            {categoryBreakdown.map((entry) => (
              <Cell key={entry.name} fill={entry.color} />
            ))}
          </Pie>
          <Tooltip formatter={(value: number) => [`${value}%`, ""]} />
        </PieChart>
      </ResponsiveContainer>

      <ul className="mt-2 space-y-2">
        {categoryBreakdown.map((cat) => (
          <li key={cat.name} className="flex items-center justify-between text-sm">
            <span className="flex items-center gap-2 text-muted">
              <span className="h-2.5 w-2.5 rounded-full" style={{ background: cat.color }} />
              {cat.name}
            </span>
            <span className="font-medium text-ink">{cat.value}%</span>
          </li>
        ))}
      </ul>
    </article>
  );
}

import { AlertTriangle } from "lucide-react";
import { lowStockItems } from "../data/mockData";

export function LowStockList() {
  return (
    <article className="rounded-xl border border-line bg-panel p-6">
      <header className="mb-4 flex items-center gap-2">
        <AlertTriangle size={18} className="text-accent-600" />
        <section>
          <h2 className="text-base font-semibold text-ink">Stok Menipis</h2>
          <p className="text-sm text-muted">Perlu restock segera</p>
        </section>
      </header>

      <ul className="space-y-4">
        {lowStockItems.map((item) => {
          const pct = Math.min(100, Math.round((item.stock / item.min) * 100));
          return (
            <li key={item.sku}>
              <section className="mb-1.5 flex items-center justify-between text-sm">
                <span className="font-medium text-ink">{item.name}</span>
                <span className="text-muted">
                  {item.stock} / {item.min} {item.unit}
                </span>
              </section>
              <motion.div className="h-2 overflow-hidden rounded-full bg-brand-100">
                <span
                  className={`block h-full rounded-full ${pct < 40 ? "bg-accent-500" : "bg-brand-500"}`}
                  style={{ width: `${pct}%` }}
                />
              </motion.div>
              <p className="mt-1 text-xs text-muted">SKU: {item.sku}</p>
            </li>
          );
        })}
      </ul>
    </article>
  );
}

import { Eye, MapPin } from "lucide-react";
import { propertyListings } from "../data/mockData";

const statusStyles: Record<string, string> = {
  Tersedia: "text-brand-600",
  Reserved: "text-amber-700",
  Terjual: "text-muted",
};

export function PropertyListings() {
  return (
    <article className="rounded-xl border border-line bg-panel p-6">
      <header className="mb-4 flex items-center justify-between">
        <section>
          <h2 className="text-base font-semibold text-ink">Listing Properti</h2>
