        </section>
        <button type="button" className="text-sm font-medium text-brand-600 hover:text-brand-700">
          + Tambah listing
        </button>
      </header>

      <ul className="space-y-3">
        {propertyListings.map((prop) => (
          <li
            key={prop.title}
            className="rounded-lg border border-line p-4 transition-colors hover:border-brand-300 hover:bg-brand-50/40"
          >
            <section className="flex items-start justify-between gap-3">
              <section className="min-w-0 flex-1">
                <p className="truncate font-medium text-ink">{prop.title}</p>
                <p className="mt-1 flex items-center gap-1 text-xs text-muted">
                  <MapPin size={12} />
                  {prop.type}
                </p>
              </section>
              <span className={`shrink-0 text-xs font-semibold ${statusStyles[prop.status]}`}>
                {prop.status}
              </span>
            </section>
            <section className="mt-3 flex items-center justify-between">
              <p className="text-lg font-semibold text-ink">{prop.price}</p>
              <span className="flex items-center gap-3 text-xs text-muted">
                <span className="flex items-center gap-1">
                  <Eye size={12} />
                  {prop.views}
                </span>
                <span className="font-medium text-brand-600">{prop.leads} leads</span>
              </span>
            </section>
          </li>
        ))}
      </ul>
    </article>
  );
}

import {
  Building2,
  DollarSign,
  Package,
  ShoppingCart,
  TrendingUp,
  Users,
} from "lucide-react";
import { stats } from "../data/mockData";
import { CategoryChart } from "./CategoryChart";
import { Header } from "./Header";
import { LowStockList } from "./LowStockList";
import { OrdersTable } from "./OrdersTable";
import { PropertyListings } from "./PropertyListings";
import { SalesChart } from "./SalesChart";
import { StatCard } from "./StatCard";

export function Dashboard() {
  return (
    <>
      <Header
        title="Dashboard"
        subtitle="Ringkasan penjualan material bangunan & properti — Mei 2026"
      />

      <main className="flex-1 overflow-y-auto p-8">
        <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">
          <StatCard
            label="Total Penjualan"
            value={stats.revenue.value}
            change={stats.revenue.change}
            up={stats.revenue.up}
            icon={<DollarSign size={20} />}
            accent="brand"
          />
          <StatCard
            label="Pesanan Aktif"
            value={stats.orders.value}
            change={stats.orders.change}
            up={stats.orders.up}
            icon={<ShoppingCart size={20} />}
          />
          <StatCard
            label="SKU Material"
            value={stats.materials.value}
            change={stats.materials.change}
            up={stats.materials.up}
            icon={<Package size={20} />}
          />
          <StatCard
            label="Listing Properti"
            value={stats.properties.value}
            change={stats.properties.change}
            up={stats.properties.up}
            icon={<Building2 size={20} />}
            accent="accent"
          />
          <StatCard
            label="Stok Menipis"
            value={stats.lowStock.value}
            change={stats.lowStock.change}
            up={stats.lowStock.up}
            icon={<TrendingUp size={20} />}
            accent="neutral"
          />
          <StatCard
            label="Leads Properti"
            value={stats.pendingLeads.value}
            change={stats.pendingLeads.change}
            up={stats.pendingLeads.up}
            icon={<Users size={20} />}
            accent="accent"
          />
        </section>

        <section className="mt-6 grid gap-6 lg:grid-cols-3">
          <section className="lg:col-span-2">
            <SalesChart />
          </section>
          <CategoryChart />
        </section>

        <section className="mt-6 grid gap-6 xl:grid-cols-3">
          <section className="xl:col-span-2">
            <OrdersTable />
          </section>
          <section className="space-y-6">
            <LowStockList />
            <PropertyListings />
          </section>
        </section>
      </main>
    </>
  );
}

import { useState } from "react";
import { Dashboard } from "./components/Dashboard";
import { Sidebar } from "./components/Sidebar";

const pageTitles: Record<string, { title: string; subtitle: string }> = {
  dashboard: {
    title: "Dashboard",
    subtitle: "Ringkasan penjualan material bangunan & properti",
  },
  material: {
    title: "Material Bangunan",
    subtitle: "Kelola katalog semen, besi, keramik, dan lainnya",
  },
  properti: {
    title: "Properti",
    subtitle: "Kelola listing rumah, tanah, apartemen, dan ruko",
  },
  pesanan: { title: "Pesanan", subtitle: "Lacak semua transaksi material & properti" },
  pelanggan: { title: "Pelanggan", subtitle: "Database kontraktor, developer, dan pembeli" },
  laporan: { title: "Laporan", subtitle: "Analitik penjualan dan performa bisnis" },
  pengaturan: { title: "Pengaturan", subtitle: "Konfigurasi toko dan akun admin" },
};

function PlaceholderPage({ id }: { id: string }) {
  const page = pageTitles[id] ?? pageTitles.dashboard;
  return (
    <main className="flex flex-1 flex-col">
      <header className="border-b border-line bg-panel px-8 py-5">
        <h1 className="font-display text-3xl text-ink">{page.title}</h1>
        <p className="mt-0.5 text-sm text-muted">{page.subtitle}</p>
      </header>
      <section className="flex flex-1 items-center justify-center p-8">
        <article className="max-w-md rounded-xl border border-line bg-panel p-8 text-center">
          <p className="font-display text-2xl text-ink">Segera hadir</p>
          <p className="mt-2 text-sm text-muted">
            Halaman <strong>{page.title}</strong> sedang dalam pengembangan. Gunakan menu
            Dashboard untuk melihat ringkasan bisnis.
          </p>
        </article>
      </section>
    </main>
  );
}

export default function App() {
  const [activeNav, setActiveNav] = useState("dashboard");

  return (
    <motion.div className="flex h-full min-h-screen">
      <Sidebar active={activeNav} onNavigate={setActiveNav} />
      <motion.div className="flex min-w-0 flex-1 flex-col">
        {activeNav === "dashboard" ? <Dashboard /> : <PlaceholderPage id={activeNav} />}
      </motion.div>
    </motion.div>
  );
}
